(() => {
  'use strict';
  const packet=window.BB_CURRENT_FIVE_AXES;
  const pairs=packet.pairDossiers||[];
  const aliases=packet.memberAliases||{};
  const pairById=new Map(pairs.map(row=>[row.subjectId,row]));
  packet.applyDetail=row=>{
    const replacement=aliases[row.subjectId];
    if(row.format==='11s'&&replacement&&pairById.has(replacement))return pairById.get(replacement);
    const patch=packet.overlays[row.subjectId+'|'+row.format];
    if(!patch)return row;
    row.axes=row.axes.map(axis=>patch.axes[axis.id]||axis);
    if(patch.axes.adaptability)row.adaptability=patch.axes.adaptability;
    row.teamImportance=patch.importance;
    return row;
  };
  const data=window.BB_STANDARD_TASK_EXPERIMENT_V1;
  data.dossiers=data.dossiers.filter(row=>!(row.format==='11s'&&aliases[row.subjectId])).map(packet.applyDetail).concat(pairs);
  data.summary.currentFiveAxes=true;
  data.summary.pairedStarObjects=pairs.length;
  data.summary.currentCanonicalPersonal11s=187;
  data.summary.currentCanonicalPersonalAllFormats=311;
  if(window.ATLAS_DATA&&packet.pairAtlas){
    const old=window.ATLAS_DATA.stars||[];
    window.BB_STAR_PAIR_MEMBER_ARCHIVE=old.filter(row=>aliases[row.id]);
    window.ATLAS_DATA.stars=old.filter(row=>!aliases[row.id]).concat(packet.pairAtlas);
  }
  window.BB_STAR_PAIR_ALIASES=aliases;
})();
